	internal class DragDropSample
	{
		public DragDropSample(int fileSize, int[] chunkSizes, string message)
		{
			this.FileSize = fileSize;
			this.ChunkSizes = chunkSizes;
			this.Message = message;
		}

		public int FileSize { get; private set; }

		public IEnumerable<int> ChunkSizes { get; private set; }

		public string Message { get; private set; }

		public IEnumerable<string> CreateChunkedMessages()
		{
			if (Message.Length != FileSize)
			{
				throw new InvalidOperationException("Unit test setup is not valid");
			}

			int position = 0;

			return ChunkSizes
					.Select((size, index) =>
							{
								var chunk = Message.Substring(position, size);
								position += size;

								WtsApi.ChannelFlags flags = WtsApi.ChannelFlags.Middle;

								if (index == 0)
								{
									flags = WtsApi.ChannelFlags.First;
								}
								else if (index == ChunkSizes.Count() - 1)
								{
									flags = WtsApi.ChannelFlags.Last;
								}

								return CreateEncodedMessage(chunk, FileSize, flags);
							})
					.ToList();
		}

		string CreateEncodedMessage(string chunk, int fileSize, WtsApi.ChannelFlags flags)
		{
			byte[] buffer = new byte[chunk.Length + 8]; // Mimic CHANNEL_PDU_LENGTH.

			Array.Copy(BitConverter.GetBytes(fileSize), 0, buffer, 0, 4);
			Array.Copy(BitConverter.GetBytes((int)flags), 0, buffer, 4, 4);
			Array.Copy(Encoding.ASCII.GetBytes(chunk), 0, buffer, 8, chunk.Length);

			return Convert.ToBase64String(buffer);
		}
	}
